input.command:
R=/tmp/explore/config/run.sh; W=/tmp/explore/config/w3
t(){ printf '%s\n' "$2" > $W/atlas.hcl; echo "### CONFIG: $1"; cat $W/atlas.hcl; $R $W schema inspect --env "$3"; }
t "name interp atlas.env" 'env {
  name = "${atlas.env}"
  url  = "sqlite://test.db"
}' fixed
t "name = upper(atlas.env)" 'env {
  name = upper(atlas.env)
  url  = "sqlite://test.db"
}' FIXED
t "labeled + name attr" 'env "lbl" {
  name = "other"
  url  = "sqlite://test.db"
}' lbl

